INSERT INTO `dossier` (`code_el`, `label_el`, `created_at`, `updated_at`) VALUES
(1, '<span style=\"color: #0000ff;\">Une photocopie certifi&eacute;e d\'acte de naissance datant de moins de trois (3) mois /</span><span style=\"color: rgb(237, 28,36);\"><i>A certified photocopy of a birth certificate issued within the last three (3) months. </span>', '2024-06-23 16:05:05', '2024-06-23 16:05:05'),
(2, '<span style=\"color: #0000ff;\">Une photocopie certifiée conforme du diplôme/attestation de réussite du Baccalauréat ou du GCE A/L  pour les premières années ou diplôme/attestation de licence (classique ou professionnelle ou technologique), BTS, HND, DUT, DEUG ou du diplôme équivalent /</span>', '2024-06-23 16:10:01', '2024-06-23 16:10:01'),
(3, '<span style=\"color: #0000ff;\">Un certificat médical délivré par un médecin fonctionnaire, datant de moins de trois (03) mois et certifiant que le candidat est apte à poursuivre des études sup', '2024-06-23 16:10:52', '2024-06-23 16:10:52'),
(4, '<span style=\"color: #0000ff;\">Quatre(04) photos d\'identité 4x4 du candidat / </span><span style=\"color:rgb(237,28, 36);\"><i>Four (04) 4x4 identity photos of the candidate</i></span> ', '2024-06-23 16:10:52', '2024-06-23 16:10:52'),
(5, '<span style=\"color: #0000ff;\">Un reçu de versement bancaire d\'un montant de 20 000F CFA pour les 1<sup>ieme</sup>années et de vingt cinq mille (25 000) F pour les 3<sup>ieme</sup> années représentant les droits d\'inscription au concours de l\'ESTLC de l\'Université d\'Ebolowa à versé au compte CCA Cameroun, <b>N° 10039-10012-00272768601-40</b> dans les agences du cameroun</span> ', '2024-06-23 16:19:45', '2024-06-23 16:19:45'),
(6, '<span style=\"color: #0000ff;\">Une enveloppe A4 timbrée au tarif réglementaire et portant l\'adresse exacte du candidat / </span><span style=\"color:rgb(237,28, 36);\"><i>An A4 envelope stamped at the standard rate and bearing the candidate\'s exact address.</span>', '2024-06-23 16:38:53', '2024-06-23 16:38:53');
