INSERT INTO `presentation` (`code_pres`, `code_bureau`, `photo_chef`, `message_chef`, `cursus_ing`, `grille_ing`, `science_ing`, `grille_science`, `nom_chef`, `created_at`, `updated_at`) VALUES
(5, 'GI', 'photo_GI.png', '<p><span lang=\"FR\" style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Calibri\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-theme-font: minor-bidi; mso-ansi-language: FR; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">: </span><span lang=\"FR\" style=\"font-size: 12.0pt; line-height: 107%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-ansi-language: FR; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Le d&eacute;partement a pour objectif de former des &eacute;tudiants capables de r&eacute;aliser tout type de logiciel permettant de r&eacute;soudre un probl&egrave;me pr&eacute;cis. Les &eacute;tudiants form&eacute;s pourront travailler &agrave; leur propre compte (auto-emploi) ou alors pourront dans n&rsquo;importe quelle entreprise de renom.</span></p>', '<p class=\"MsoNormal\" style=\"text-align: justify; line-height: 150%;\"><span lang=\"FR\" style=\"font-size: 12.0pt; line-height: 150%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\';\">Le parcours Ing&eacute;nieur :</span></p>\r\n<p class=\"LO-normal\" style=\"text-align: justify; line-height: 150%; margin: 11.0pt 0cm 10.0pt 0cm;\"><span lang=\"FR\" style=\"font-size: 12.0pt; line-height: 150%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\';\">- G&eacute;nie Informatique des Syst&egrave;mes Logistiques Intelligents (GISLI)</span></p>\r\n<p class=\"LO-normal\" style=\"text-align: justify; line-height: 150%; margin: 12.0pt 0cm 10.0pt 0cm;\"><span lang=\"FR\" style=\"font-size: 12.0pt; line-height: 150%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\';\">- G&eacute;nie informatique des Syst&egrave;mes audiovisuels et logistique (GISAL) </span></p>\r\n<p><span lang=\"FR\" style=\"font-size: 12.0pt; line-height: 107%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: FR; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">- G&eacute;nie informatique des Syst&egrave;mes de jeux Vid&eacute;o (GISJV)</span></p>', NULL, '<p class=\"LO-normal\" style=\"margin-bottom: 8.0pt; text-align: justify;\"><span lang=\"FR\" style=\"font-size: 10.0pt; line-height: 115%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\';\">Le </span><span lang=\"FR\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\';\">parcours Sciences de l&rsquo;Ing&eacute;nieur et Technologies:</span></p>\r\n<p class=\"LO-normal\" style=\"text-align: justify; text-indent: 36.0pt; margin: 12.0pt 0cm 10.0pt 0cm;\"><span lang=\"FR\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\';\">- Syst&egrave;me d&rsquo;Information Logistique et G&eacute;nie Logiciel (SILGL)</span></p>\r\n<p class=\"LO-normal\" style=\"text-align: justify; text-indent: 36.0pt; margin: 12.0pt 0cm 10.0pt 0cm;\"><span lang=\"FR\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\';\">- R&eacute;seaux Informatiques et Syst&egrave;mes Logistiques (RISL) </span></p>\r\n<p class=\"LO-normal\" style=\"text-align: justify; text-indent: 36.0pt; margin: 12.0pt 0cm 10.0pt 0cm;\"><span lang=\"FR\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\';\">- Intelligence Artificiel et Logistique (IAL) </span></p>\r\n<p><span lang=\"FR\" style=\"font-size: 12.0pt; line-height: 107%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: FR; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\"><span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>- M&eacute;thodes Informatiques Appliqu&eacute;s &agrave; la Gestion Logistique (MIAGE)</span></p>', NULL, 'Dr MESSI NGUELE Thomas', '2024-02-20 12:43:32', '2024-02-20 12:43:32'),
(6, 'GT', 'photo_GT.jpg', '<p>Departement de G&eacute;nie des Transports</p>', '<p>-Aeronotique</p>\r\n<p>-Transport Naval</p>\r\n<p>-Transport Feroviaire</p>\r\n<p>-Transport Routier</p>', NULL, NULL, NULL, 'Dr DIBOMA', '2024-02-20 15:57:39', '2024-02-20 15:57:39');
INSERT INTO `presentation` (`code_pres`, `code_bureau`, `photo_chef`, `message_chef`, `cursus_ing`, `grille_ing`, `science_ing`, `grille_science`, `nom_chef`, `created_at`, `updated_at`) VALUES
(7, 'RO', 'photo_RO.png', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"FR\" style=\"font-size: 12.0pt; line-height: 107%; font-family: \'Times New Roman\',serif;\">le d&eacute;partement de recherche op&eacute;rationnelle<span style=\"mso-spacerun: yes;\">&nbsp; </span>(R&nbsp;.O)&nbsp;</span><span lang=\"FR-CM\" style=\"font-size: 12.0pt; line-height: 107%; font-family: \'Times New Roman\',serif; mso-ansi-language: FR-CM;\">de l&rsquo;&Eacute;cole Sup&eacute;rieure de Transport, de Logistique et de Commerce (ESTLC) de l&rsquo;Universit&eacute; d&rsquo;Ebolowa &agrave; Ambam&nbsp;, </span><span lang=\"FR\" style=\"font-size: 12.0pt; line-height: 107%; font-family: \'Times New Roman\',serif;\">en formation initiale comme en formation continue,&nbsp;propose une large gamme de programmes &agrave;<span style=\"mso-spacerun: yes;\">&nbsp; </span>tous ceux qui souhaitent vivre une exp&eacute;rience d&rsquo;apprentissage hors du commun, fortifier leurs talents, exprimer leur leadership et devenir des ing&eacute;nieurs et managers de haut niveau.</span></p>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"FR\" style=\"font-size: 12.0pt; line-height: 107%; font-family: \'Times New Roman\',serif;\"><strong>-Mod&eacute;lisation et Simulation (MES)</strong>: <span style=\"font-family: Roboto-Regular; font-size: 13pt; color: rgb(35,31,32); font-style: normal; font-variant: normal;\">Former des professionnelles capables de concevoir, analyser, mettre en &oelig;uvre et valider des mod&egrave;les math&eacute;matiques et des solutions num&eacute;riques pour des probl&egrave;mes concrets d&rsquo;ing&eacute;nierie dans les domaines de l&rsquo;industrie, de la sant&eacute; et des services (m&eacute;canique des fluides, a&eacute;ronautique, fiance, environnement, etc...)</span><br></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"FR\" style=\"font-size: 12.0pt; line-height: 107%; font-family: \'Times New Roman\',serif;\"><strong>-G&eacute;nie de gestion (GDG) ou Engineering Management:</strong> <span style=\"font-family: Roboto-Regular; font-size: 13pt; color: rgb(35,31,32); font-style: normal; font-variant: normal;\">Dans ce scenario, l&rsquo;ing&eacute;nieur est appel&eacute; &agrave; associer aux r&ocirc;les techniques traditionnels qui le caract&eacute;risent, des connaissances et habitudes multiples et vari&eacute;s : de la compr&eacute;hension des sc&eacute;-narios de consommation au d&eacute;veloppement de solutions innovantes, de l&rsquo;analyse des dynamiques organisationnelles &agrave; la projection de nouveaux mod&egrave;les<br>comp&eacute;titifs.<br style=\"font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: 2; text-align: -webkit-auto; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px;\"></span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"FR\" style=\"font-size: 12.0pt; line-height: 107%; font-family: \'Times New Roman\',serif;\">-<strong>March&eacute; Financier et Trading (MET):</strong> &nbsp;<span style=\"font-family: Roboto-Regular; font-size: 13pt; color: rgb(35,31,32); font-style: normal; font-variant: normal;\">Former des ing&eacute;nieurs comp&eacute;tents dans la plupart des domaines des march&eacute;s fianciers (traders, sales, brokers, analystes fianciers, analystes quantitatifs, gestionnaires de risques, gestionnaires de portefeuilles, etc.)<br style=\"font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: 2; text-align: -webkit-auto; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px;\"></span><span style=\"font-family: Roboto-Regular; font-size: 13pt; color: rgb(35,31,32); font-style: normal; font-variant: normal;\"><br style=\"font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: 2; text-align: -webkit-auto; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px;\"></span><br></span></p>', '<p style=\'margin-top:0cm;margin-right:0cm;margin-bottom:10.0pt;margin-left:0cm;line-height:115%;font-size:15px;font-family:\"Calibri\",sans-serif;text-align:justify;\'><strong><span style=\'font-size:19px;line-height:115%;font-family:\"Times New Roman\",serif;\'>Cursus&nbsp;:</span></strong><span style=\'font-size:19px;line-height:115%;font-family:\"Times New Roman\",serif;\'>&nbsp;Ing&eacute;nieur</span></p>\r\n<p style=\'margin-top:0cm;margin-right:0cm;margin-bottom:0cm;margin-left:0cm;line-height:normal;font-size:15px;font-family:\"Calibri\",sans-serif;text-align:justify;\'><strong><span style=\'font-size:24px;font-family:\"Times New Roman\",serif;\'>MODELISATION ET SIMULATION &nbsp; (MES)</span></strong></p>\r\n<p style=\'margin-top:0cm;margin-right:0cm;margin-bottom:0cm;margin-left:0cm;line-height:normal;font-size:15px;font-family:\"Calibri\",sans-serif;text-align:justify;\'><strong><span style=\'font-size:24px;font-family:\"Times New Roman\",serif;\'>Niveau 3</span></strong></p>\r\n<p style=\'margin-top:0cm;margin-right:0cm;margin-bottom:0cm;margin-left:0cm;line-height:normal;font-size:15px;font-family:\"Calibri\",sans-serif;text-align:justify;\'><strong><span style=\'font-size:16px;font-family:\"Times New Roman\",serif;\'>&nbsp;</span></strong></p>\r\n<p style=\'margin-top:0cm;margin-right:0cm;margin-bottom:0cm;margin-left:0cm;line-height:normal;font-size:15px;font-family:\"Calibri\",sans-serif;text-align:justify;\'><strong><span style=\'font-size:16px;font-family:\"Times New Roman\",serif;\'>SEMESTRE 5</span></strong></p>\r\n<p style=\'margin-top:0cm;margin-right:0cm;margin-bottom:0cm;marg