INSERT INTO `site_etude` (`code_site`, `label_site`, `description_site`, `created_at`, `updated_at`) VALUES
(1, 'ESTLC(Ecole Supérieure de Transport, de Logistique et de Commerce)', '<p>En choisissant l&rsquo;ESTLC comme site d&rsquo;&eacute;tude, voici les informations &agrave; savoir</p>\r\n<ol>\r\n<li>Les Droits Universitaires s&rsquo;&eacute;l&egrave;veront &agrave; <strong>50.000</strong> FCFA par an</li>\r\n<li>Les Frais m&eacute;dicaux couteront <strong>5.000</strong> FCFA</li>\r\n<li>La formation se d&eacute;roulera au campus de l&rsquo;ESTLC sis &agrave; AMBAM situ&eacute; dans le Sud Cameroun &agrave; environ 250KM de la ville de Yaound&eacute;.</li>\r\n</ol>', '2024-06-14 17:52:00', '2024-06-14 17:52:00'),
(2, 'ISLAPE(Institut Supérieure La Perle)', '<p>En choisissant ISLAPE comme site d&rsquo;&eacute;tude, voici les informations &agrave; savoir&nbsp;:</p>\r\n<ol>\r\n<li>Les Droits Universitaires s&rsquo;&eacute;l&egrave;veront &agrave; <strong>550.000</strong> FCFA par an</li>\r\n<li>Les Frais m&eacute;dicaux couteront <strong>5.000</strong> FCFA</li>\r\n</ol>\r\n<p>La formation se d&eacute;roulera au sein des campus d&rsquo;ISLAPE de la ville de Douala &agrave; YASSA et AKWA.</p>', '2024-06-14 17:52:00', '2024-06-14 17:52:00');
